def marker_shape(x, marker):
 pts=[(r,c) for r in range(len(x)) for c in range(len(x[0])) if x[r][c]==marker]
 r0=min(r for r,c in pts); c0=min(c for r,c in pts)
 return {(r-r0,c-c0) for r,c in pts},(r0,c0)
